INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('036027a1-737b-5781-8d7e-a099c0599c55', 'Hungary (XII. 11.) Government decree on registration and data', '309/2014. (XII. 11.) Government decree on registration and data provision obligations related to waste', 'The Hungarian Government''s 2014 "309/2014. (XII. 11.) Korm. Rendelet" regulates waste management and outlines the obligations of businesses regarding record-keeping and data reporting related to waste management. The regulation requires businesses to maintain detailed records of the generation, handling, and disposal of waste, as well as report the data to relevant authorities. Businesses must also ensure compliance with waste management regulations and take measures to prevent and mitigate environmental damage caused by their waste. Failure to comply with the regulation can result in penalties and legal action.', 'The Hungarian Government''s 2014 "309/2014. (XII. 11.) Korm. Rendelet" regulates waste management and outlines the obligations of businesses regarding record-keeping and data reporting related to waste management. The regulation requires businesses to maintain detailed records of the generation, handling, and disposal of waste, as well as report the data to relevant authorities. Businesses must also ensure compliance with waste management regulations and take measures to prevent and mitigate environmental damage caused by their waste. Failure to comply with the regulation can result in penalties and legal action.', 'The Hungarian Government''s 2014 "309/2014. (XII. 11.) Korm. Rendelet" regulates waste management and outlines the obligations of businesses regarding record-keeping and data reporting related to waste management. The regulation requires businesses to maintain detailed records of the generation, handling, and disposal of waste, as well as report the data to relevant authorities. Businesses must also ensure compliance with waste management regulations and take measures to prevent and mitigate environmental damage caused by their waste. Failure to comply with the regulation can result in penalties and legal action.', 'Hungary', 'climate', 'in_force', '2014-01-01'::date, 'Hungary', 'https://www.carrotsandsticks.org/policies/76_14', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'hungary', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a2a86b72-b5ca-5530-b029-35d4c65bc62c', 'Hungary CLXXXV of 2012 law about waste', 'CLXXXV of 2012 law about waste', 'The Parliament, in order to protect the environment and human health, mitigate the environmental impact, manage natural resources sparingly, reduce the effects of resource use, improve its efficiency, ensure long-term competitiveness and prevent or reduce the generation of waste, preventing the harmful effects of generated waste, reducing its quantity and danger, and reusing used products, keeping materials in the consumption chain in a production-consumption cycle, and utilizing as much of the waste as possible, and environmentally friendly non-useful, non-recyclable waste in order to dispose of it, creates the following law.', 'The Parliament, in order to protect the environment and human health, mitigate the environmental impact, manage natural resources sparingly, reduce the effects of resource use, improve its efficiency, ensure long-term competitiveness and prevent or reduce the generation of waste, preventing the harmful effects of generated waste, reducing its quantity and danger, and reusing used products, keeping materials in the consumption chain in a production-consumption cycle, and utilizing as much of the waste as possible, and environmentally friendly non-useful, non-recyclable waste in order to dispose of it, creates the following law.', 'The Parliament, in order to protect the environment and human health, mitigate the environmental impact, manage natural resources sparingly, reduce the effects of resource use, improve its efficiency, ensure long-term competitiveness and prevent or reduce the generation of waste, preventing the harmful effects of generated waste, reducing its quantity and danger, and reusing used products, keeping materials in the consumption chain in a production-consumption cycle, and utilizing as much of the waste as possible, and environmentally friendly non-useful, non-recyclable waste in order to dispose of it, creates the following law.', 'Hungary', 'climate', 'in_force', '2012-01-01'::date, 'Hungary', 'https://www.carrotsandsticks.org/policies/76_17', ARRAY['sdg2', 'regulations', 'sdg7', 'sdg9', 'mandatory', 'hungary', 'sdg12', 'disclosure', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c9f4d7a8-a048-506b-b5af-5306011b5948', 'Hungary Corporate Governance Recommendations', 'Corporate Governance Recommendations 2012', 'The CGR are considered to be an addition to relevant Hungarian legislation (predominantly Act IV of 2006 on business associations, hereinafter Company Act), primarily for listed, public limited companies registered in Hungary. On no account shall recommendations included in the CGR be regarded as recommendations contrary to the provisions of law. The CGR contain recommendations, suggestions and related explanations.', 'The CGR are considered to be an addition to relevant Hungarian legislation (predominantly Act IV of 2006 on business associations, hereinafter Company Act), primarily for listed, public limited companies registered in Hungary. On no account shall recommendations included in the CGR be regarded as recommendations contrary to the provisions of law. The CGR contain recommendations, suggestions and related explanations.', 'The CGR are considered to be an addition to relevant Hungarian legislation (predominantly Act IV of 2006 on business associations, hereinafter Company Act), primarily for listed, public limited companies registered in Hungary. On no account shall recommendations included in the CGR be regarded as recommendations contrary to the provisions of law. The CGR contain recommendations, suggestions and related explanations.', 'Hungary', 'governance', 'in_force', '2012-01-01'::date, 'Hungary', 'https://www.carrotsandsticks.org/policies/76_4', ARRAY['guidance_frameworks', 'hungary', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('81732fa4-9445-56e5-acb8-1f633fff12bd', 'Hungary (I. 14.) VM decree on the rules related', '6/2011. (I. 14.) VM decree on the rules related to the examination, control and evaluation of the air pollution level and the emission of stationary air pollution sources', 'The 6/2011. (I. 14.) VM decree in Hungary focuses on regulating the examination, control, and evaluation of air pollution levels and emissions from stationary sources. It outlines requirements for measuring air pollution, setting up measuring points, and using specific methods to monitor pollutants. The decree aims to ensure compliance with emission limit values and protect air quality. It applies to individuals, companies, and organizations operating stationary air pollution sources, emphasizing the importance of accurate measurements and reporting. The policy is mandatory and sets clear guidelines for monitoring and reducing air pollution.', 'The 6/2011. (I. 14.) VM decree in Hungary focuses on regulating the examination, control, and evaluation of air pollution levels and emissions from stationary sources. It outlines requirements for measuring air pollution, setting up measuring points, and using specific methods to monitor pollutants. The decree aims to ensure compliance with emission limit values and protect air quality. It applies to individuals, companies, and organizations operating stationary air pollution sources, emphasizing the importance of accurate measurements and reporting. The policy is mandatory and sets clear guidelines for monitoring and reducing air pollution.', 'The 6/2011. (I. 14.) VM decree in Hungary focuses on regulating the examination, control, and evaluation of air pollution levels and emissions from stationary sources. It outlines requirements for measuring air pollution, setting up measuring points, and using specific methods to monitor pollutants. The decree aims to ensure compliance with emission limit values and protect air quality. It applies to individuals, companies, and organizations operating stationary air pollution sources, emphasizing the importance of accurate measurements and reporting. The policy is mandatory and sets clear guidelines for monitoring and reducing air pollution.', 'Hungary', 'climate', 'in_force', '2011-01-01'::date, 'Hungary', 'https://www.carrotsandsticks.org/policies/76_11', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'hungary']::text[]) ON CONFLICT (id) DO NOTHING;
