INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3a01a061-8b6c-5b2a-b080-a36ddd2895d4', 'Hungary Act CLXXV of 2011 on the Freedom', 'Act CLXXV of 2011 on the Freedom of Association, Non-profit Status and the Operation and Support of Civil Organizations (Civil Act)', 'The Act regulates Hungarian public benefit organizations, NGOs, civil organizations and non-profit organizations. Civil organizations are obligated, inter alia, to publish an annual public benefit report, including activity and financial report, report on any budgetary support, report on any grants given, value or amount of compensation provided to leading officials, and report on assets management.', 'The Act regulates Hungarian public benefit organizations, NGOs, civil organizations and non-profit organizations. Civil organizations are obligated, inter alia, to publish an annual public benefit report, including activity and financial report, report on any budgetary support, report on any grants given, value or amount of compensation provided to leading officials, and report on assets management.', 'The Act regulates Hungarian public benefit organizations, NGOs, civil organizations and non-profit organizations. Civil organizations are obligated, inter alia, to publish an annual public benefit report, including activity and financial report, report on any budgetary support, report on any grants given, value or amount of compensation provided to leading officials, and report on assets management.', 'Hungary', 'climate', 'in_force', '2011-01-01'::date, 'Hungary', 'https://www.carrotsandsticks.org/policies/76_5', ARRAY['mandatory', 'other sustainability policy', 'hungary', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
