INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c74347ec-25a7-5f44-8cf3-dd19211fe575', 'Hungary Corporate Governance Recommendations', 'Corporate Governance Recommendations 2004', 'The Recommendations – as expressed by the title – make suggestions regarding recommended, applicable practices. Alignment and compliance with the Recommendations are recommended, but not mandatory for companies listed on the stock exchange.', 'The Recommendations – as expressed by the title – make suggestions regarding recommended, applicable practices. Alignment and compliance with the Recommendations are recommended, but not mandatory for companies listed on the stock exchange.', 'The Recommendations – as expressed by the title – make suggestions regarding recommended, applicable practices. Alignment and compliance with the Recommendations are recommended, but not mandatory for companies listed on the stock exchange.', 'Hungary', 'governance', 'in_force', '2004-01-01'::date, 'Hungary', 'https://www.carrotsandsticks.org/policies/76_3', ARRAY['guidance_frameworks', 'hungary', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1e505428-1f17-51b7-b4ff-a5556bc19302', 'Hungary LIII of 1995 law on the general rules', 'LIII of 1995 law on the general rules for the protection of the environment', 'The Parliament, considering that the natural heritage and environmental values are part of the national wealth, the preservation and protection of which, and the improvement of their quality, are a basic condition in terms of the living world, human health and quality of life; without this, the harmony between human activity and nature cannot be maintained, failure to do so endangers the health of present generations, the existence of future generations and the survival of many species, therefore, in accordance with the provisions of the Basic Law, the following law is created.', 'The Parliament, considering that the natural heritage and environmental values are part of the national wealth, the preservation and protection of which, and the improvement of their quality, are a basic condition in terms of the living world, human health and quality of life; without this, the harmony between human activity and nature cannot be maintained, failure to do so endangers the health of present generations, the existence of future generations and the survival of many species, therefore, in accordance with the provisions of the Basic Law, the following law is created.', 'The Parliament, considering that the natural heritage and environmental values are part of the national wealth, the preservation and protection of which, and the improvement of their quality, are a basic condition in terms of the living world, human health and quality of life; without this, the harmony between human activity and nature cannot be maintained, failure to do so endangers the health of present generations, the existence of future generations and the survival of many species, therefore, in accordance with the provisions of the Basic Law, the following law is created.', 'Hungary', 'climate', 'in_force', '1995-01-01'::date, 'Hungary', 'https://www.carrotsandsticks.org/policies/76_9', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg6', 'hungary', 'sdg12', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dc62dec0-59ad-5b2b-b3e1-7808fa65cb13', 'Hungary XCIII of 1993 law about labor protection', 'XCIII of 1993 law about labor protection', 'The personal, material and organizational conditions of safe and non-health-threatening work in order to protect the health and working ability of organized workers and to humanize working conditions, thereby preventing work accidents and occupational diseases, the duties, rights and rights of the state, employers and employees defining its duties, the Parliament creates the following law.', 'The personal, material and organizational conditions of safe and non-health-threatening work in order to protect the health and working ability of organized workers and to humanize working conditions, thereby preventing work accidents and occupational diseases, the duties, rights and rights of the state, employers and employees defining its duties, the Parliament creates the following law.', 'The personal, material and organizational conditions of safe and non-health-threatening work in order to protect the health and working ability of organized workers and to humanize working conditions, thereby preventing work accidents and occupational diseases, the duties, rights and rights of the state, employers and employees defining its duties, the Parliament creates the following law.', 'Hungary', 'nature', 'in_force', '1993-01-01'::date, 'Hungary', 'https://www.carrotsandsticks.org/policies/76_12', ARRAY['sdg8', 'sdg14', 'regulations', 'mandatory', 'hungary', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c19cb694-8656-57a5-9289-2a72103d55f3', 'Iceland EU Emissions Trading Scheme Act', '96/2023 EU Emissions Trading Scheme Act.', 'The 96/2023 EU Emissions Trading Scheme Act in Iceland regulates greenhouse gas emissions from various activities falling under the EU Emissions Trading System scope. It specifies definitions, responsibilities, and permits required for businesses, airlines, and shipping companies to operate in compliance with emission limits and reporting obligations.', 'The 96/2023 EU Emissions Trading Scheme Act in Iceland regulates greenhouse gas emissions from various activities falling under the EU Emissions Trading System scope. It specifies definitions, responsibilities, and permits required for businesses, airlines, and shipping companies to operate in compliance with emission limits and reporting obligations.', 'The 96/2023 EU Emissions Trading Scheme Act in Iceland regulates greenhouse gas emissions from various activities falling under the EU Emissions Trading System scope. It specifies definitions, responsibilities, and permits required for businesses, airlines, and shipping companies to operate in compliance with emission limits and reporting obligations.', 'Iceland', 'climate', 'in_force', '2023-01-01'::date, 'Iceland', 'https://www.carrotsandsticks.org/policies/77_11', ARRAY['sdg13', 'regulations', 'iceland', 'mandatory', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('644cb91e-6762-5fc8-8eb2-4502631ad71e', 'Iceland ESG Reporting Guide 2.0. A Support Resource', 'ESG Reporting Guide 2.0. A Support Resource for Companies May 2019', 'This guide was created primarily for companies, but investors, exchanges, regulators, and other capital market stakeholders have contributed much to it. As a primer on the current practice and enduring value of ESG management and data reporting, we hope this guide brings clarity and synthesis to a crowded marketplace, not additional confusion. The Nasdaq ESG Reporting Guide is also, by design, a living document. The version is significantly revised, and it is expected to do so on a regular basis as new issues emerge, existing standards shift, and calculation methodologies improve.', 'This guide was created primarily for companies, but investors, exchanges, regulators, and other capital market stakeholders have contributed much to it. As a primer on the current practice and enduring value of ESG management and data reporting, we hope this guide brings clarity and synthesis to a crowded marketplace, not additional confusion. The Nasdaq ESG Reporting Guide is also, by design, a living document. The version is significantly revised, and it is expected to do so on a regular basis as new issues emerge, existing standards shift, and calculation methodologies improve.', 'This guide was created primarily for companies, but investors, exchanges, regulators, and other capital market stakeholders have contributed much to it. As a primer on the current practice and enduring value of ESG management and data reporting, we hope this guide brings clarity and synthesis to a crowded marketplace, not additional confusion. The Nasdaq ESG Reporting Guide is also, by design, a living document. The version is significantly revised, and it is expected to do so on a regular basis as new issues emerge, existing standards shift, and calculation methodologies improve.', 'Iceland', 'climate', 'in_force', '2019-01-01'::date, 'Iceland', 'https://www.carrotsandsticks.org/policies/77_9', ARRAY['iceland', 'mandatory', 'mandatory_regulations', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d33da04b-016b-54c7-b224-d2766a237cd0', 'data collection and disclosure by institutions for Iceland''s', 'Regulation on data collection and disclosure by institutions for Iceland''s accounting of greenhouse gas emissions and carbon sequestration from the atmosphere. 520/17', 'The policy in Iceland focuses on data collection and disclosure by institutions to account for greenhouse gas emissions and carbon sequestration. It aligns with international commitments and involves the Environment Agency overseeing emissions reporting, with specific reporting requirements for various sectors.', 'The policy in Iceland focuses on data collection and disclosure by institutions to account for greenhouse gas emissions and carbon sequestration. It aligns with international commitments and involves the Environment Agency overseeing emissions reporting, with specific reporting requirements for various sectors.', 'The policy in Iceland focuses on data collection and disclosure by institutions to account for greenhouse gas emissions and carbon sequestration. It aligns with international commitments and involves the Environment Agency overseeing emissions reporting, with specific reporting requirements for various sectors.', 'Iceland', 'climate', 'in_force', '2017-01-01'::date, 'Iceland', 'https://www.carrotsandsticks.org/policies/77_12', ARRAY['sdg13', 'regulations', 'iceland', 'mandatory', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b735c1b9-bb9f-503f-9987-24c8614bd934', 'Iceland Act amending the Annual Accounts Act', 'Act amending the Annual Accounts Act, no. 3/2006', 'The Act amends the Annual Accounts Act in Iceland to simplify and implement the Annual Accounts Directive 2013/34/EU. It applies to various types of companies like public and private limited companies, cooperatives, and non-profit institutions engaged in business operations. The Act defines terms like International Accounting Standards and sets criteria for micro, small, medium-sized, and large companies, based on total assets, net turnover, and average number of man-years. Companies related to the public interest are classified as large companies. The Act outlines reporting requirements and thresholds based on financial criteria.', 'The Act amends the Annual Accounts Act in Iceland to simplify and implement the Annual Accounts Directive 2013/34/EU. It applies to various types of companies like public and private limited companies, cooperatives, and non-profit institutions engaged in business operations. The Act defines terms like International Accounting Standards and sets criteria for micro, small, medium-sized, and large companies, based on total assets, net turnover, and average number of man-years. Companies related to the public interest are classified as large companies. The Act outlines reporting requirements and thresholds based on financial criteria.', 'The Act amends the Annual Accounts Act in Iceland to simplify and implement the Annual Accounts Directive 2013/34/EU. It applies to various types of companies like public and private limited companies, cooperatives, and non-profit institutions engaged in business operations. The Act defines terms like International Accounting Standards and sets criteria for micro, small, medium-sized, and large companies, based on total assets, net turnover, and average number of man-years. Companies related to the public interest are classified as large companies. The Act outlines reporting requirements and thresholds based on financial criteria.', 'Iceland', 'climate', 'in_force', '2016-01-01'::date, 'Iceland', 'https://www.carrotsandsticks.org/policies/77_4', ARRAY['regulations', 'iceland', 'mandatory', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
