INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9910a921-7906-5b40-b5f5-b06f98c1cb0b', 'Iceland Climate Act', 'Climate Act No 70/2012', 'The Climate Act No 70/2012 in Iceland aims to reduce greenhouse gas emissions, increase carbon sequestration, and facilitate adaptation to climate change. It applies to various activities impacting emissions and aviation operations within the European Economic Area, overseen by the Ministry of the Environment.', 'The Climate Act No 70/2012 in Iceland aims to reduce greenhouse gas emissions, increase carbon sequestration, and facilitate adaptation to climate change. It applies to various activities impacting emissions and aviation operations within the European Economic Area, overseen by the Ministry of the Environment.', 'The Climate Act No 70/2012 in Iceland aims to reduce greenhouse gas emissions, increase carbon sequestration, and facilitate adaptation to climate change. It applies to various activities impacting emissions and aviation operations within the European Economic Area, overseen by the Ministry of the Environment.', 'Iceland', 'climate', 'in_force', '2012-01-01'::date, 'Iceland', 'https://www.carrotsandsticks.org/policies/77_10', ARRAY['sdg13', 'regulations', 'iceland', 'mandatory', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
