INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cb98ec53-683f-5f6b-86b9-7a37c9f660de', 'Iceland Strengthening of the Green Economy', 'The Strengthening of the Green Economy', 'This report includes 48 actions that will need to be implemented between 2013 and 2014. One of the actions is that all institutions of the respective ministries and all state-owned companies should publish annual reports using GRI’s Framework.', 'This report includes 48 actions that will need to be implemented between 2013 and 2014. One of the actions is that all institutions of the respective ministries and all state-owned companies should publish annual reports using GRI’s Framework.', 'This report includes 48 actions that will need to be implemented between 2013 and 2014. One of the actions is that all institutions of the respective ministries and all state-owned companies should publish annual reports using GRI’s Framework.', 'Iceland', 'climate', 'in_force', '2011-01-01'::date, 'Iceland', 'https://www.carrotsandsticks.org/policies/77_2', ARRAY['sdg4', 'other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'iceland', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
