INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f3241f1e-47f9-541c-900e-d0d59f156dba', 'Iceland green accounting', 'Regulation on green accounting', 'The purpose of this regulation is to provide the public, NGOs and the government with information on how environmental issues are handled in activities that may cause pollution. Furthermore, the aim of the regulation is to encourage operators to closely monitor the main environmental aspects of the operation and seek to ensure that the development of the operation is positive for the environment.', 'The purpose of this regulation is to provide the public, NGOs and the government with information on how environmental issues are handled in activities that may cause pollution. Furthermore, the aim of the regulation is to encourage operators to closely monitor the main environmental aspects of the operation and seek to ensure that the development of the operation is positive for the environment.', 'The purpose of this regulation is to provide the public, NGOs and the government with information on how environmental issues are handled in activities that may cause pollution. Furthermore, the aim of the regulation is to encourage operators to closely monitor the main environmental aspects of the operation and seek to ensure that the development of the operation is positive for the environment.', 'Iceland', 'climate', 'in_force', '2002-01-01'::date, 'Iceland', 'https://www.carrotsandsticks.org/policies/77_3', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'iceland', 'mandatory', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4c3677b5-107b-5932-9e5c-b07daf424334', 'Draft Framework of India’s Climate Finance Taxonomy', 'Draft Framework of India’s Climate Finance Taxonomy', 'The Draft Framework of India’s Climate Finance Taxonomy outlines objectives, principles, and sectoral coverage for activities contributing to India’s climate commitments. Targeted at stakeholders in finance, government, and environmental sectors, it aims to classify and guide climate finance investments in line with India’s climate action goals.', 'The Draft Framework of India’s Climate Finance Taxonomy outlines objectives, principles, and sectoral coverage for activities contributing to India’s climate commitments. Targeted at stakeholders in finance, government, and environmental sectors, it aims to classify and guide climate finance investments in line with India’s climate action goals.', 'The Draft Framework of India’s Climate Finance Taxonomy outlines objectives, principles, and sectoral coverage for activities contributing to India’s climate commitments. Targeted at stakeholders in finance, government, and environmental sectors, it aims to classify and guide climate finance investments in line with India’s climate action goals.', 'India', 'climate', 'in_force', '2025-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_55', ARRAY['india', 'voluntary_frameworks', 'sdg13', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('af15f57a-a01c-5c83-b2de-8ed48c3f2e4e', 'India Environment, Social and Governance (ESG) Debt Securities (other', 'Framework for Environment, Social and Governance (ESG) Debt Securities (other than green debt securities)', 'The 2025 Indian policy outlines the framework for Environment, Social, and Governance (ESG) Debt Securities to specify issuance standards for social, sustainability, and sustainability-linked bonds. Issuers, stock exchanges, bankers, depositories, trustees, and ESG rating providers are targeted for compliance with regulations on ESG debt securities.', 'The 2025 Indian policy outlines the framework for Environment, Social, and Governance (ESG) Debt Securities to specify issuance standards for social, sustainability, and sustainability-linked bonds. Issuers, stock exchanges, bankers, depositories, trustees, and ESG rating providers are targeted for compliance with regulations on ESG debt securities.', 'The 2025 Indian policy outlines the framework for Environment, Social, and Governance (ESG) Debt Securities to specify issuance standards for social, sustainability, and sustainability-linked bonds. Issuers, stock exchanges, bankers, depositories, trustees, and ESG rating providers are targeted for compliance with regulations on ESG debt securities.', 'India', 'governance', 'in_force', '2025-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_56', ARRAY['india', 'sdg16', 'voluntary_frameworks', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('42e1820a-924f-585d-9af3-c8a1da3d7b2d', 'India Harit Sagar - Green Port Guidelines', 'Harit Sagar - Green Port Guidelines 2023', 'These Green Port Guidelines equip India''s major ports to reduce carbon emissions. By planning actions across port operations, the document targets quantified reductions through green interventions. It guides sustainable development and port operation, aiming for carbon neutrality without harming nearby ecosystems. The guidelines integrate sustainability throughout the organization, pushing for eco-friendly materials, practices, and technologies.', 'These Green Port Guidelines equip India''s major ports to reduce carbon emissions. By planning actions across port operations, the document targets quantified reductions through green interventions. It guides sustainable development and port operation, aiming for carbon neutrality without harming nearby ecosystems. The guidelines integrate sustainability throughout the organization, pushing for eco-friendly materials, practices, and technologies.', 'These Green Port Guidelines equip India''s major ports to reduce carbon emissions. By planning actions across port operations, the document targets quantified reductions through green interventions. It guides sustainable development and port operation, aiming for carbon neutrality without harming nearby ecosystems. The guidelines integrate sustainability throughout the organization, pushing for eco-friendly materials, practices, and technologies.', 'India', 'climate', 'in_force', '2023-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_53', ARRAY['guidance_frameworks', 'sdg13', 'india', 'sdg6', 'disclosure', 'sdg15', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8e4224c4-6681-5289-b0ad-ab9c79a9691e', 'India New category of Mutual Fund schemes for Environmental', 'New category of Mutual Fund schemes for Environmental, Social and Governance (“ESG”) Investing and related disclosures by Mutual Funds 2023', 'Under the extant regulatory requirements, Mutual Funds are permitted to launch only one scheme with ESG investing under the thematic category for Equity schemes. In view of the industry representations for allowing multiple schemes with different ESG strategies and considering the increasing need for green financing, it has been decided to permit launch of multiple ESG schemes with different strategies by Mutual Funds.', 'Under the extant regulatory requirements, Mutual Funds are permitted to launch only one scheme with ESG investing under the thematic category for Equity schemes. In view of the industry representations for allowing multiple schemes with different ESG strategies and considering the increasing need for green financing, it has been decided to permit launch of multiple ESG schemes with different strategies by Mutual Funds.', 'Under the extant regulatory requirements, Mutual Funds are permitted to launch only one scheme with ESG investing under the thematic category for Equity schemes. In view of the industry representations for allowing multiple schemes with different ESG strategies and considering the increasing need for green financing, it has been decided to permit launch of multiple ESG schemes with different strategies by Mutual Funds.', 'India', 'climate', 'in_force', '2023-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_54', ARRAY['india', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8fd122a7-7495-59c1-8ebd-08b5c44bc0b5', 'India Business Responsibility and Sustainability Reporting (BRSR)', 'Business Responsibility and Sustainability Reporting (BRSR)', 'The "Guidance Note for Business Responsibility & Sustainability Reporting (BRSR)" outlines a framework for Indian listed entities to disclose sustainability-related information. The policy facilitates alignment with internationally recognized reporting standards such as GRI, SASB, and TCFD. It emphasizes principles from the National Guidelines for Responsible Business Conduct (NGRBC), promoting ethical, transparent, and accountable business practices. The document includes detailed instructions on disclosures related to governance, environmental impact, social responsibility, and stakeholder engagement. Key sections include guidance on reporting boundaries, metrics for sustainable sourcing, gender inclusivity, and grievance redressal mechanisms. It also addresses energy and water use, greenhouse gas emissions, and waste management. Businesses are encouraged to provide clear, concise, and comprehensive disclosures while avoiding redundancy by cross-referencing information already reported elsewhere. By implementing this framework, entities aim to enhance transparency, comparability, and accountability in sustainability reporting.', 'The "Guidance Note for Business Responsibility & Sustainability Reporting (BRSR)" outlines a framework for Indian listed entities to disclose sustainability-related information. The policy facilitates alignment with internationally recognized reporting standards such as GRI, SASB, and TCFD. It emphasizes principles from the National Guidelines for Responsible Business Conduct (NGRBC), promoting ethical, transparent, and accountable business practices. The document includes detailed instructions on disclosures related to governance, environmental impact, social responsibility, and stakeholder engagement. Key sections include guidance on reporting boundaries, metrics for sustainable sourcing, gender inclusivity, and grievance redressal mechanisms. It also addresses energy and water use, greenhouse gas emissions, and waste management. Businesses are encouraged to provide clear, concise, and comprehensive disclosures while avoiding redundancy by cross-referencing information already reported elsewhere. By implementing this framework, entities aim to enhance transparency, comparability, and accountability in sustainability reporting.', 'The "Guidance Note for Business Responsibility & Sustainability Reporting (BRSR)" outlines a framework for Indian listed entities to disclose sustainability-related information. The policy facilitates alignment with internationally recognized reporting standards such as GRI, SASB, and TCFD. It emphasizes principles from the National Guidelines for Responsible Business Conduct (NGRBC), promoting ethical, transparent, and accountable business practices. The document includes detailed instructions on disclosures related to governance, environmental impact, social responsibility, and stakeholder engagement. Key sections include guidance on reporting boundaries, metrics for sustainable sourcing, gender inclusivity, and grievance redressal mechanisms. It also addresses energy and water use, greenhouse gas emissions, and waste management. Businesses are encouraged to provide clear, concise, and comprehensive disclosures while avoiding redundancy by cross-referencing information already reported elsewhere. By implementing this framework, entities aim to enhance transparency, comparability, and accountability in sustainability reporting.', 'India', 'climate', 'in_force', '2022-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_400', ARRAY['sdg13', 'india', 'sdg7', 'mandatory', 'sdg6', 'sdg5', 'sdg16', 'mandatory_regulations', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('81a66163-7c6c-51eb-950a-11bc01cd4e58', 'India Business Responsibility and Sustainability Reporting by listed entities', 'Business Responsibility and Sustainability Reporting by listed entities', 'Business Responsibility and Sustainability Reporting (BRSR) by listed entities 2021 is a set of guidelines developed by the Securities and Exchange Board of India (SEBI) to promote sustainability reporting among listed companies in India. The BRSR guidelines require listed companies to disclose their sustainability performance and provide information on how they manage environmental, social, and governance (ESG) risks and opportunities. The guidelines cover several key areas, including governance and ethics, environmental sustainability, social sustainability, human rights, and stakeholder engagement. The guidelines are mandatory for the top 1000 listed companies in India, based on market capitalization, and compliance is required starting from the financial year 2022-23. The guidelines provide a framework for companies to report on their sustainability performance in a structured and standardized manner.', 'Business Responsibility and Sustainability Reporting (BRSR) by listed entities 2021 is a set of guidelines developed by the Securities and Exchange Board of India (SEBI) to promote sustainability reporting among listed companies in India. The BRSR guidelines require listed companies to disclose their sustainability performance and provide information on how they manage environmental, social, and governance (ESG) risks and opportunities. The guidelines cover several key areas, including governance and ethics, environmental sustainability, social sustainability, human rights, and stakeholder engagement. The guidelines are mandatory for the top 1000 listed companies in India, based on market capitalization, and compliance is required starting from the financial year 2022-23. The guidelines provide a framework for companies to report on their sustainability performance in a structured and standardized manner.', 'Business Responsibility and Sustainability Reporting (BRSR) by listed entities 2021 is a set of guidelines developed by the Securities and Exchange Board of India (SEBI) to promote sustainability reporting among listed companies in India. The BRSR guidelines require listed companies to disclose their sustainability performance and provide information on how they manage environmental, social, and governance (ESG) risks and opportunities. The guidelines cover several key areas, including governance and ethics, environmental sustainability, social sustainability, human rights, and stakeholder engagement. The guidelines are mandatory for the top 1000 listed companies in India, based on market capitalization, and compliance is required starting from the financial year 2022-23. The guidelines provide a framework for companies to report on their sustainability performance in a structured and standardized manner.', 'India', 'climate', 'in_force', '2021-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_52', ARRAY['india', 'sdg11', 'sdg7', 'mandatory', 'sdg17', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('aa54c334-ee8e-5e75-b84f-a85487c79a2d', 'India Report of the Committee on Business Responsibility Reporting', 'Report of the Committee on Business Responsibility Reporting', 'In the report, the Committee recommends a new two-format reporting framework called ''''Business Responsibility and Sustainability Report (BRSR)''''. The Business Responsibility and Sustainability Report (BRSR) provides guidelines for the preparation of Business Responsibility Reporting for listed and unlisted companies in India. The Committee’s new Framework takes into consideration the global developments in non-financial sustainability reporting, which increasingly require businesses to be responsible and sustainable towards the environment and society.', 'In the report, the Committee recommends a new two-format reporting framework called ''''Business Responsibility and Sustainability Report (BRSR)''''. The Business Responsibility and Sustainability Report (BRSR) provides guidelines for the preparation of Business Responsibility Reporting for listed and unlisted companies in India. The Committee’s new Framework takes into consideration the global developments in non-financial sustainability reporting, which increasingly require businesses to be responsible and sustainable towards the environment and society.', 'In the report, the Committee recommends a new two-format reporting framework called ''''Business Responsibility and Sustainability Report (BRSR)''''. The Business Responsibility and Sustainability Report (BRSR) provides guidelines for the preparation of Business Responsibility Reporting for listed and unlisted companies in India. The Committee’s new Framework takes into consideration the global developments in non-financial sustainability reporting, which increasingly require businesses to be responsible and sustainable towards the environment and society.', 'India', 'climate', 'in_force', '2020-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_47', ARRAY['sdg13', 'india', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3b5bf812-342d-58fd-9e4c-bf212f2f1d73', 'India National Guidelines on Responsible Business Conduct', 'National Guidelines on Responsible Business Conduct', 'The Ministry of Corporate Affairs (MCA), Government of India, released a set of guidelines in 2011 called the National Voluntary Guidelines on the Social, Environmental and Economic Responsibilities of Business (NVGs). This was expected to provide guidance to businesses on what constitutes responsible business conduct.', 'The Ministry of Corporate Affairs (MCA), Government of India, released a set of guidelines in 2011 called the National Voluntary Guidelines on the Social, Environmental and Economic Responsibilities of Business (NVGs). This was expected to provide guidance to businesses on what constitutes responsible business conduct.', 'The Ministry of Corporate Affairs (MCA), Government of India, released a set of guidelines in 2011 called the National Voluntary Guidelines on the Social, Environmental and Economic Responsibilities of Business (NVGs). This was expected to provide guidance to businesses on what constitutes responsible business conduct.', 'India', 'climate', 'in_force', '2019-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_24', ARRAY['guidance_frameworks', 'sdg2', 'sdg3', 'india', 'sdg11', 'sdg7', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('08f4a25b-1b28-55d1-bb4e-aa1452597eeb', 'India Stewardship Code for All Mutual Funds and All', 'Stewardship Code for All Mutual Funds and All Categories of Aifs, in Relation to Their Investment in Listed Equities Circular', 'Stewardship Responsibilities of institutional investors are intended to protect their clients'' wealth "by enhancing monitoring and engagement with their investee companies". This circular codifies these responsibilities for all Mutual Funds and Alternative Investment Funds.', 'Stewardship Responsibilities of institutional investors are intended to protect their clients'' wealth "by enhancing monitoring and engagement with their investee companies". This circular codifies these responsibilities for all Mutual Funds and Alternative Investment Funds.', 'Stewardship Responsibilities of institutional investors are intended to protect their clients'' wealth "by enhancing monitoring and engagement with their investee companies". This circular codifies these responsibilities for all Mutual Funds and Alternative Investment Funds.', 'India', 'governance', 'in_force', '2019-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_25', ARRAY['india', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b84f5213-3dcd-5105-9c83-46620b2be320', 'India Guidance Document on ESG Disclosures', 'Guidance Document on ESG Disclosures', 'BSE is introducing this ESG Guidance to assist listed corporates wishing to incorporate ESG reporting into their existing reporting processes.', 'BSE is introducing this ESG Guidance to assist listed corporates wishing to incorporate ESG reporting into their existing reporting processes.', 'BSE is introducing this ESG Guidance to assist listed corporates wishing to incorporate ESG reporting into their existing reporting processes.', 'India', 'climate', 'in_force', '2018-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_23', ARRAY['guidance_frameworks', 'other sustainability policy', 'india', 'sdg7', 'mandatory', 'sdg6', 'sdg16', 'sdg12', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('181b17bc-95c0-5c54-bdcf-516efc42a7db', 'India Integrated Reporting by Listed Entities Circular', 'Integrated Reporting by Listed Entities Circular', 'The circular recommends, Integrated Reporting may be adopted on a voluntary basis from the financial year 2017-18 by top 500 listed companies which are required to prepare BRR.', 'The circular recommends, Integrated Reporting may be adopted on a voluntary basis from the financial year 2017-18 by top 500 listed companies which are required to prepare BRR.', 'The circular recommends, Integrated Reporting may be adopted on a voluntary basis from the financial year 2017-18 by top 500 listed companies which are required to prepare BRR.', 'India', 'climate', 'in_force', '2017-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_18', ARRAY['india', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f426fb6a-a70a-5ab3-9d86-e5c2db874483', 'Corporate Governance for Insurers in India', 'Guidelines for Corporate Governance for Insurers in India', 'The objective of the guidelines is to ensure that the structure, responsibilities and functions of Board of Directors and the management of the company recognize the expectations of all stakeholders as well as those of the regulator. The structure should take steps required to adopt sound and prudent principles and practices for the governance of the company and should have the ability to quickly address issues of non-compliance or weak oversight and controls. These guidelines therefore amplify on certain issues which are covered in the Insurance Act, 1938 and the regulations framed thereunder and include measures which are additionally considered essential by IRDAI for adoption by insurers.', 'The objective of the guidelines is to ensure that the structure, responsibilities and functions of Board of Directors and the management of the company recognize the expectations of all stakeholders as well as those of the regulator. The structure should take steps required to adopt sound and prudent principles and practices for the governance of the company and should have the ability to quickly address issues of non-compliance or weak oversight and controls. These guidelines therefore amplify on certain issues which are covered in the Insurance Act, 1938 and the regulations framed thereunder and include measures which are additionally considered essential by IRDAI for adoption by insurers.', 'The objective of the guidelines is to ensure that the structure, responsibilities and functions of Board of Directors and the management of the company recognize the expectations of all stakeholders as well as those of the regulator. The structure should take steps required to adopt sound and prudent principles and practices for the governance of the company and should have the ability to quickly address issues of non-compliance or weak oversight and controls. These guidelines therefore amplify on certain issues which are covered in the Insurance Act, 1938 and the regulations framed thereunder and include measures which are additionally considered essential by IRDAI for adoption by insurers.', 'India', 'governance', 'in_force', '2016-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_13', ARRAY['guidance_frameworks', 'india', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('729e1d6c-5e46-5396-bc85-45f387ce7b8a', 'India BioMedical Waste Management and Handling Rules', 'BioMedical Waste Management and Handling Rules', 'The BioMedical Waste Management and Handling Rules of 2016 in India aim to improve the collection, segregation, processing, treatment, and disposal of bio-medical waste to reduce its environmental impact. It supersedes the 1998 rules and applies to entities generating, collecting, storing, transporting, or handling bio-medical waste in various healthcare-related settings. The rules were developed under the Environment (Protection) Act, 1986, to protect human health and the environment from the adverse effects of bio-medical waste management.', 'The BioMedical Waste Management and Handling Rules of 2016 in India aim to improve the collection, segregation, processing, treatment, and disposal of bio-medical waste to reduce its environmental impact. It supersedes the 1998 rules and applies to entities generating, collecting, storing, transporting, or handling bio-medical waste in various healthcare-related settings. The rules were developed under the Environment (Protection) Act, 1986, to protect human health and the environment from the adverse effects of bio-medical waste management.', 'The BioMedical Waste Management and Handling Rules of 2016 in India aim to improve the collection, segregation, processing, treatment, and disposal of bio-medical waste to reduce its environmental impact. It supersedes the 1998 rules and applies to entities generating, collecting, storing, transporting, or handling bio-medical waste in various healthcare-related settings. The rules were developed under the Environment (Protection) Act, 1986, to protect human health and the environment from the adverse effects of bio-medical waste management.', 'India', 'climate', 'in_force', '2016-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_27', ARRAY['sdg4', 'sdg13', 'regulations', 'india', 'sdg11', 'mandatory', 'sdg12', 'disclosure', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4917440b-5ed7-5e01-8f47-720a294b8f6b', 'India Notification of Plastic Waste Management Rules', 'Notification of Plastic Waste Management Rules', 'The Plastic Waste Management Rules, 2016 aim to: Increase minimum thickness of plastic carry bags from 40 to 50 microns and stipulate minimum thickness of 50 micron for  plastic sheets also to facilitate collection and recycle of plastic waste, Expand the jurisdiction of applicability from the municipal area to rural areas, because plastic has reached rural areas also; To bring in the responsibilities of producers and generators, both in plastic waste management system and to introduce collect back system of plastic waste by the producers/brand owners, as per extended producers responsibility; To introduce collection of plastic waste management fee through pre-registration of the producers, importers of plastic carry bags/multilayered packaging and vendors selling the same for establishing the waste management system; To promote use of plastic waste for road construction as per Indian Road Congress guidelines or energy recovery, or waste to oil etc. for gainful utilization of waste and also address the waste disposal issue; to entrust more responsibility on waste generators, namely payment of user charge as prescribed by local authority, collection and handing over of waste by the institutional generator, event organizers.', 'The Plastic Waste Management Rules, 2016 aim to: Increase minimum thickness of plastic carry bags from 40 to 50 microns and stipulate minimum thickness of 50 micron for  plastic sheets also to facilitate collection and recycle of plastic waste, Expand the jurisdiction of applicability from the municipal area to rural areas, because plastic has reached rural areas also; To bring in the responsibilities of producers and generators, both in plastic waste management system and to introduce collect back system of plastic waste by the producers/brand owners, as per extended producers responsibility; To introduce collection of plastic waste management fee through pre-registration of the producers, importers of plastic carry bags/multilayered packaging and vendors selling the same for establishing the waste management system; To promote use of plastic waste for road construction as per Indian Road Congress guidelines or energy recovery, or waste to oil etc. for gainful utilization of waste and also address the waste disposal issue; to entrust more responsibility on waste generators, namely payment of user charge as prescribed by local authority, collection and handing over of waste by the institutional generator, event organizers.', 'The Plastic Waste Management Rules, 2016 aim to: Increase minimum thickness of plastic carry bags from 40 to 50 microns and stipulate minimum thickness of 50 micron for  plastic sheets also to facilitate collection and recycle of plastic waste, Expand the jurisdiction of applicability from the municipal area to rural areas, because plastic has reached rural areas also; To bring in the responsibilities of producers and generators, both in plastic waste management system and to introduce collect back system of plastic waste by the producers/brand owners, as per extended producers responsibility; To introduce collection of plastic waste management fee through pre-registration of the producers, importers of plastic carry bags/multilayered packaging and vendors selling the same for establishing the waste management system; To promote use of plastic waste for road construction as per Indian Road Congress guidelines or energy recovery, or waste to oil etc. for gainful utilization of waste and also address the waste disposal issue; to entrust more responsibility on waste generators, namely payment of user charge as prescribed by local authority, collection and handing over of waste by the institutional generator, event organizers.', 'India', 'climate', 'in_force', '2016-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_29', ARRAY['guidance_frameworks', 'sdg13', 'sdg9', 'india', 'sdg11', 'sdg7', 'mandatory', 'sdg12', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d8ab4599-aa3d-584f-bd04-5048f5c39500', 'India Notification of Hazardous and Other Wastes Rules', 'Notification of Hazardous and Other Wastes Rules', 'This notification set out rules that shall apply to the management of hazardous and other wastes as specified in the Schedules to these rules.', 'This notification set out rules that shall apply to the management of hazardous and other wastes as specified in the Schedules to these rules.', 'This notification set out rules that shall apply to the management of hazardous and other wastes as specified in the Schedules to these rules.', 'India', 'climate', 'in_force', '2016-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_38', ARRAY['sdg13', 'india', 'mandatory', 'mandatory_regulations', 'sdg12', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('57792811-a426-5ffc-9ea6-a82183558eb6', 'India E-Waste (Management) Rules', 'E-Waste (Management) Rules 2016', 'The Government of India (GoI) introduced the E-Waste Management Rules in 2016. The rules apply to businesses that are generating electronic waste items. The rules specify that businesses should make arrangements for the safe disposal of scrapped electronic items.', 'The Government of India (GoI) introduced the E-Waste Management Rules in 2016. The rules apply to businesses that are generating electronic waste items. The rules specify that businesses should make arrangements for the safe disposal of scrapped electronic items.', 'The Government of India (GoI) introduced the E-Waste Management Rules in 2016. The rules apply to businesses that are generating electronic waste items. The rules specify that businesses should make arrangements for the safe disposal of scrapped electronic items.', 'India', 'climate', 'in_force', '2016-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_51', ARRAY['sdg13', 'other sustainability policy', 'sdg9', 'india', 'mandatory', 'mandatory_regulations', 'sdg12', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('66dbefe0-3045-5031-889a-5c9d3a168d09', 'India Format for Business Responsibility Report (BRR) Circular', 'Format for Business Responsibility Report (BRR) Circular', 'This Circular is issued as an updated component of SEBI''s Listing Obligations and Disclosure requirements. It presents in the annex a format on how the reports have to be structured and what information it needs to contain, it mostly covers ESG factors and Corporate Governance.', 'This Circular is issued as an updated component of SEBI''s Listing Obligations and Disclosure requirements. It presents in the annex a format on how the reports have to be structured and what information it needs to contain, it mostly covers ESG factors and Corporate Governance.', 'This Circular is issued as an updated component of SEBI''s Listing Obligations and Disclosure requirements. It presents in the annex a format on how the reports have to be structured and what information it needs to contain, it mostly covers ESG factors and Corporate Governance.', 'India', 'climate', 'in_force', '2015-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_3', ARRAY['sdg4', 'sdg2', 'india', 'sdg7', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7d8f45b5-7083-524b-a1c3-5e893793160e', 'Securities and Exchange Board of India (Listing Obligations', 'Securities and Exchange Board of India (Listing Obligations and Disclosure Requirements) Regulations, 2015', 'These regulations may be called the Securities and Exchange Board of India (Listing Obligations and Disclosure Requirements) Regulations, 2015.(2) They shall come into force on the ninetieth day from the date of their publication in the Official Gazette: Provided that the provisions of sub-regulation (4) of regulation 23 and regulation 31A shall come into force on the date of notification of these regulations.', 'These regulations may be called the Securities and Exchange Board of India (Listing Obligations and Disclosure Requirements) Regulations, 2015.(2) They shall come into force on the ninetieth day from the date of their publication in the Official Gazette: Provided that the provisions of sub-regulation (4) of regulation 23 and regulation 31A shall come into force on the date of notification of these regulations.', 'These regulations may be called the Securities and Exchange Board of India (Listing Obligations and Disclosure Requirements) Regulations, 2015.(2) They shall come into force on the ninetieth day from the date of their publication in the Official Gazette: Provided that the provisions of sub-regulation (4) of regulation 23 and regulation 31A shall come into force on the date of notification of these regulations.', 'India', 'governance', 'in_force', '2015-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_42', ARRAY['india', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('181e9e92-aa7f-5652-a721-a4f03e9e1acf', 'India Format of compliance report on Corporate Governance', 'Format of compliance report on Corporate Governance by Listed Entities Circular', 'Regulation  27(2)  of  Securities  and  Exchange  Board  of  India (Listing  Obligations and Disclosure  Requirements)  Regulations, 2015 (“Listing Regulations”), specifies that the listed entity shall submit quarterly compliance reports on corporate governance in the format specified by the Board from time to time to recognised Stock Exchange(s) within fifteen days from close of the quarter.', 'Regulation  27(2)  of  Securities  and  Exchange  Board  of  India (Listing  Obligations and Disclosure  Requirements)  Regulations, 2015 (“Listing Regulations”), specifies that the listed entity shall submit quarterly compliance reports on corporate governance in the format specified by the Board from time to time to recognised Stock Exchange(s) within fifteen days from close of the quarter.', 'Regulation  27(2)  of  Securities  and  Exchange  Board  of  India (Listing  Obligations and Disclosure  Requirements)  Regulations, 2015 (“Listing Regulations”), specifies that the listed entity shall submit quarterly compliance reports on corporate governance in the format specified by the Board from time to time to recognised Stock Exchange(s) within fifteen days from close of the quarter.', 'India', 'climate', 'in_force', '2015-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_46', ARRAY['other sustainability policy', 'india', 'mandatory', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('341ceb30-5861-545b-9ce5-2ec5c5f670a6', 'India Corporate Governance in listed entities - Amendments', 'Corporate Governance in listed entities - Amendments to Clause 49 of the Equity Listing Agreement', 'This circular is in continuation to circular No. CIR/CFD/POLICY CELL/2/2014 dated April 17, 2014  on  amendments to Clauses 35B and 49 of the Equity Listing Agreement.', 'This circular is in continuation to circular No. CIR/CFD/POLICY CELL/2/2014 dated April 17, 2014  on  amendments to Clauses 35B and 49 of the Equity Listing Agreement.', 'This circular is in continuation to circular No. CIR/CFD/POLICY CELL/2/2014 dated April 17, 2014  on  amendments to Clauses 35B and 49 of the Equity Listing Agreement.', 'India', 'governance', 'in_force', '2014-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_22', ARRAY['other sustainability policy', 'india', 'mandatory', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('707618c0-d481-56be-b5d7-4beef04074ab', 'India Corporate Social Responsibility and Sustainability for Central Public', 'Guidelines on Corporate Social Responsibility and Sustainability for Central Public Sector Enterprises', 'The DPE Guidelines have been developed for CPSEs in order for them to commit and achieving their respective targets in a manner that is beneficial to them and their stakeholders. These guidelines aim to better promote transparency in disclosing strategies and activities.', 'The DPE Guidelines have been developed for CPSEs in order for them to commit and achieving their respective targets in a manner that is beneficial to them and their stakeholders. These guidelines aim to better promote transparency in disclosing strategies and activities.', 'The DPE Guidelines have been developed for CPSEs in order for them to commit and achieving their respective targets in a manner that is beneficial to them and their stakeholders. These guidelines aim to better promote transparency in disclosing strategies and activities.', 'India', 'governance', 'in_force', '2014-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_4', ARRAY['guidance_frameworks', 'india', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('53d24a2f-1461-55db-9df2-b9cbb9b1cc4d', 'India Consultative Paper on Review of Corporate Governance Norms', 'Consultative Paper on Review of Corporate Governance Norms in India 2013', 'A consultation document on the need to improve further the level of corporate governance standards in India.', 'A consultation document on the need to improve further the level of corporate governance standards in India.', 'A consultation document on the need to improve further the level of corporate governance standards in India.', 'India', 'governance', 'in_force', '2013-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_10', ARRAY['india', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('03c8919a-5931-5d1f-9ec2-31e2530f01f7', 'India Companies Act', 'Companies Act', 'The "Companies Act, 2013" is a comprehensive legislative framework governing the incorporation, functioning, and regulation of companies in India. It consolidates and amends previous company laws to promote transparency, accountability, and good governance in corporate operations. Key provisions address the incorporation process, responsibilities of directors, financial disclosures, audits, and the rights of stakeholders. The Act also establishes mechanisms for resolving disputes and managing insolvency. It introduces reforms such as mandatory Corporate Social Responsibility (CSR), a specialized tribunal for company law matters, and stricter penalties for non-compliance. Provisions for digital record-keeping and electronic communications are emphasized, reflecting modern business practices. By ensuring clarity and promoting ethical practices, the Act aims to foster investor confidence and sustainable corporate growth in India.', 'The "Companies Act, 2013" is a comprehensive legislative framework governing the incorporation, functioning, and regulation of companies in India. It consolidates and amends previous company laws to promote transparency, accountability, and good governance in corporate operations. Key provisions address the incorporation process, responsibilities of directors, financial disclosures, audits, and the rights of stakeholders. The Act also establishes mechanisms for resolving disputes and managing insolvency. It introduces reforms such as mandatory Corporate Social Responsibility (CSR), a specialized tribunal for company law matters, and stricter penalties for non-compliance. Provisions for digital record-keeping and electronic communications are emphasized, reflecting modern business practices. By ensuring clarity and promoting ethical practices, the Act aims to foster investor confidence and sustainable corporate growth in India.', 'The "Companies Act, 2013" is a comprehensive legislative framework governing the incorporation, functioning, and regulation of companies in India. It consolidates and amends previous company laws to promote transparency, accountability, and good governance in corporate operations. Key provisions address the incorporation process, responsibilities of directors, financial disclosures, audits, and the rights of stakeholders. The Act also establishes mechanisms for resolving disputes and managing insolvency. It introduces reforms such as mandatory Corporate Social Responsibility (CSR), a specialized tribunal for company law matters, and stricter penalties for non-compliance. Provisions for digital record-keeping and electronic communications are emphasized, reflecting modern business practices. By ensuring clarity and promoting ethical practices, the Act aims to foster investor confidence and sustainable corporate growth in India.', 'India', 'climate', 'in_force', '2013-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_401', ARRAY['regulations', 'india', 'mandatory', 'sdg16', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ebe3a89d-bf75-5c79-99d4-75cf942a8d7e', 'India Companies Act', 'The Companies Act', 'The Companies Act, 2013 passed by the Parliament has received the assent of the President of India on 29th August, 2013.', 'The Companies Act, 2013 passed by the Parliament has received the assent of the President of India on 29th August, 2013.', 'The Companies Act, 2013 passed by the Parliament has received the assent of the President of India on 29th August, 2013.', 'India', 'governance', 'in_force', '2013-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_9', ARRAY['regulations', 'india', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cfc557d8-2a5f-50c5-bbcd-f0ee2308e990', 'India Business Responsibility Report Regulation Circular', 'Business Responsibility Report Regulation Circular', 'SEBI has, vide circular dated August 13, 2012, mandated inclusion of Business Responsibility Report (BRR) as a part of the Annual Report for top 100 listed entities. The said reporting requirement is in line with the ''National Voluntary Guidelines on Social, Environmental and Economic Responsibilities of Business (NVGs)'' notified by Ministry of Corporate Affairs, Government of India, in July, 2011.', 'SEBI has, vide circular dated August 13, 2012, mandated inclusion of Business Responsibility Report (BRR) as a part of the Annual Report for top 100 listed entities. The said reporting requirement is in line with the ''National Voluntary Guidelines on Social, Environmental and Economic Responsibilities of Business (NVGs)'' notified by Ministry of Corporate Affairs, Government of India, in July, 2011.', 'SEBI has, vide circular dated August 13, 2012, mandated inclusion of Business Responsibility Report (BRR) as a part of the Annual Report for top 100 listed entities. The said reporting requirement is in line with the ''National Voluntary Guidelines on Social, Environmental and Economic Responsibilities of Business (NVGs)'' notified by Ministry of Corporate Affairs, Government of India, in July, 2011.', 'India', 'climate', 'in_force', '2012-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_12', ARRAY['sdg10', 'regulations', 'india', 'sdg7', 'mandatory', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
